\documentclass{article}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{tikz}

\begin{document}

\begin{tikzpicture}
\begin{axis}[
    title={简单的3D曲面图示例},
    xlabel={$x$},
    ylabel={$y$},
    zlabel={$z$},
    view={60}{30},
    colormap/viridis,
    grid=major,
    width=10cm,
    height=8cm
]

\addplot3[
    surf,
    samples=25,
    domain=-3:3,
    domain y=-3:3
] 
{sin(deg(x)) * cos(deg(y))};

\end{axis}
\end{tikzpicture}

